     * @dev Converts an `address` with fixed length of 20 bytes to its not checksummed ASCII `string` hexadecimal
     * representation.
     */
    function toHexString(address addr) internal pure returns (string memory) {
        return toHexString(uint256(uint160(addr)), ADDRESS_LENGTH);
    }

    /**
     * @dev Returns true if the two strings are equal.
     */
    function equal(string memory a, string memory b) internal pure returns (bool) {
        return bytes(a).length == bytes(b).length && keccak256(bytes(a)) == keccak256(bytes(b));
    }
}

contracts/CreditToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./interfaces/IMRVOracle.sol";

contract CreditToken is ERC20, ERC20Burnable, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    struct Batch {
        uint256 batchId;
        string projectId;
        address verifier;
        string ipfsHash;
        uint256 amount;
        uint256 timestamp;
        bool isRetired;
        bool isFlagged;
    }

    uint256 private _batchIds;
    mapping(uint256 => Batch) public batches;
    mapping(uint256 => mapping(address => uint256)) public batchBalances;
    mapping(address => uint256[]) public userBatches;
    /// @notice Child batch -> batch it was fractionalized from (0 for originals).
    mapping(uint256 => uint256) public batchParent;
    /// @notice Circulating supply per batch, so a compensation pool can be
    /// divided pro-rata across holders. Invariant: sum(batchSupply) == totalSupply.
    mapping(uint256 => uint256) public batchSupply;

    /// @notice Optional external MRV feed. When unset (address(0)) minting skips
    /// attestation, preserving the original permissionless-mint behaviour.
    IMRVOracle public mrvOracle;

    event BatchMinted(
        uint256 indexed batchId,
        string projectId,
        address indexed verifier,
        string ipfsHash,
        uint256 amount,
        uint256 timestamp
    );
    event BatchRetired(uint256 indexed batchId, uint256 amount);
    event BatchFlagged(uint256 indexed batchId, bool flagged);
    event BatchSplit(
        uint256 indexed parentBatchId,
        uint256 indexed childBatchId,
        address indexed holder,
        uint256 amount
    );
    event MRVOracleUpdated(address indexed newOracle);

    constructor(address defaultAdmin) ERC20("Carbon Credit", "CC") {
        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(MINTER_ROLE, defaultAdmin);
        _grantRole(VERIFIER_ROLE, defaultAdmin);
    }

    function mintBatch(
        string calldata projectId,
        string calldata ipfsHash,
        uint256 amount
    ) external onlyRole(MINTER_ROLE) returns (uint256) {
        require(amount > 0, "Amount must be > 0");
        require(bytes(projectId).length > 0, "Project ID required");
        require(bytes(ipfsHash).length > 0, "IPFS hash required");

        // Optional MRV attestation (roadmap 3.1). Skipped when no oracle is set.
        if (address(mrvOracle) != address(0)) {
            require(mrvOracle.isProjectApproved(projectId), "Project not approved by MRV oracle");
            require(
                mrvOracle.getProjectHash(projectId) == keccak256(bytes(ipfsHash)),
                "IPFS hash does not match MRV oracle"
            );
        }

        uint256 batchId = ++_batchIds;
        Batch storage batch = batches[batchId];
        batch.batchId = batchId;
        batch.projectId = projectId;
        batch.verifier = msg.sender;
        batch.ipfsHash = ipfsHash;
        batch.amount = amount;
        batch.timestamp = block.timestamp;
        batch.isRetired = false;
        batch.isFlagged = false;

        _mint(msg.sender, amount);
        batchBalances[batchId][msg.sender] = amount;
        batchSupply[batchId] = amount;
        userBatches[msg.sender].push(batchId);

        emit BatchMinted(batchId, projectId, msg.sender, ipfsHash, amount, block.timestamp);
        return batchId;
    }

    /**
     * @dev Keeps per-batch accounting in sync on regular transfers so credits
     * move batch-tracking to the recipient (e.g. marketplace purchases).
     * Minting and retirement manage batch state explicitly (see mintBatch and
     * _retireBatch); direct burns bypass batch accounting.
     */
    function _update(address from, address to, uint256 value) internal override {
        super._update(from, to, value);
        if (from == address(0) || to == address(0) || from == to) return;

        uint256 remaining = value;
        uint256[] storage list = userBatches[from];
        uint256 i = 0;
        while (remaining > 0) {
            require(i < list.length, "Batch balance mismatch");
            uint256 batchId = list[i];
            uint256 bal = batchBalances[batchId][from];
            if (bal == 0) {
                list[i] = list[list.length - 1];
                list.pop();
                continue;
            }
            uint256 move = bal < remaining ? bal : remaining;
            batchBalances[batchId][from] = bal - move;
            if (batchBalances[batchId][to] == 0) {
                userBatches[to].push(batchId);
            }
            batchBalances[batchId][to] += move;
            remaining -= move;
            i++;
        }
    }

    function retireBatch(uint256 batchId, uint256 amount) external {
        _retireBatch(msg.sender, batchId, amount);
    }

    function retireBatchFrom(address from, uint256 batchId, uint256 amount) external {
        uint256 allowance = allowance(from, msg.sender);
        require(allowance >= amount, "Insufficient allowance");
        _approve(from, msg.sender, allowance - amount);
        _retireBatch(from, batchId, amount);
    }

    function _retireBatch(address from, uint256 batchId, uint256 amount) internal {
        require(batchBalances[batchId][from] >= amount, "Insufficient batch balance");
        require(!batches[batchId].isRetired, "Batch already fully retired");
        require(!batches[batchId].isFlagged, "Batch is flagged");

        _burn(from, amount);
        batchBalances[batchId][from] -= amount;
        batchSupply[batchId] -= amount;

        // Mark the batch fully retired once no circulating supply remains, so
        // getBatchInfo reports the terminal state and later splits are blocked.
        if (batchSupply[batchId] == 0) {
            batches[batchId].isRetired = true;
        }

        if (batchBalances[batchId][from] == 0) {
            uint256[] storage userBatchList = userBatches[from];
            for (uint256 i = 0; i < userBatchList.length; i++) {
                if (userBatchList[i] == batchId) {
                    userBatchList[i] = userBatchList[userBatchList.length - 1];
                    userBatchList.pop();
                    break;
                }
            }
        }

        uint256 totalRemaining = 0;
        for (uint256 i = 0; i < userBatches[from].length; i++) {
            totalRemaining += batchBalances[userBatches[from][i]][from];
        }
        if (totalRemaining == 0) {
            delete userBatches[from];
        }

        emit BatchRetired(batchId, amount);
    }

    /**
     * @dev Fractionalizes a batch (roadmap 4): the holder moves `amount` of
     * `batchId` into a new child batch. No tokens are minted or burned, so
     * total supply is unchanged -- this only regroups ownership so credits can
     * be traded in granular lots without splitting a whole project vintage.
     *
     * The child inherits the parent's verifier and IPFS evidence, so provenance
     * is preserved; the flag check prevents laundering a disputed batch into a
     * clean-looking child.
     */
    function splitBatch(
        uint256 batchId,
        uint256 amount,
        string calldata projectId
    ) external returns (uint256 childBatchId) {
        Batch storage parent = batches[batchId];
        require(parent.batchId != 0, "Batch not found");
        require(!parent.isFlagged, "Batch is flagged");
        require(!parent.isRetired, "Batch already fully retired");
        require(amount > 0, "Amount must be > 0");
        require(bytes(projectId).length > 0, "Project ID required");
        require(batchBalances[batchId][msg.sender] >= amount, "Insufficient batch balance");

        batchBalances[batchId][msg.sender] -= amount;
        batchSupply[batchId] -= amount;
        _removeBatchFromUserIfEmpty(msg.sender, batchId);

        childBatchId = ++_batchIds;
        Batch storage child = batches[childBatchId];
        child.batchId = childBatchId;
        child.projectId = projectId;
        child.verifier = parent.verifier;
        child.ipfsHash = parent.ipfsHash;
        child.amount = amount;
        child.timestamp = block.timestamp;
        child.isRetired = false;
        child.isFlagged = false;

        batchParent[childBatchId] = batchId;
        batchSupply[childBatchId] = amount;
        batchBalances[childBatchId][msg.sender] = amount;
        userBatches[msg.sender].push(childBatchId);

        emit BatchSplit(batchId, childBatchId, msg.sender, amount);
    }

    function _removeBatchFromUserIfEmpty(address user, uint256 batchId) internal {
        if (batchBalances[batchId][user] != 0) return;
        uint256[] storage list = userBatches[user];
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i] == batchId) {
                list[i] = list[list.length - 1];
                list.pop();
                break;
            }
        }
    }

    function flagBatch(uint256 batchId, bool flagged) external onlyRole(DEFAULT_ADMIN_ROLE) {
        batches[batchId].isFlagged = flagged;
        emit BatchFlagged(batchId, flagged);
    }

    function getBatchInfo(uint256 batchId)
        external
        view
        returns (
            string memory projectId,
            address verifier,
            string memory ipfsHash,
            uint256 amount,
            uint256 timestamp,
            bool isRetired,
            bool isFlagged
        )
    {
        Batch storage batch = batches[batchId];
        return (
            batch.projectId,
            batch.verifier,
            batch.ipfsHash,
            batch.amount,
            batch.timestamp,
            batch.isRetired,
            batch.isFlagged
        );
    }

    function getBatchVerifier(uint256 batchId) external view returns (address) {
        return batches[batchId].verifier;
    }

    function getBatchTimestamp(uint256 batchId) external view returns (uint256) {
        return batches[batchId].timestamp;
    }

    function getBatchAmount(uint256 batchId) external view returns (uint256) {
        return batches[batchId].amount;
    }

    function getBatchProjectId(uint256 batchId) external view returns (string memory) {
        return batches[batchId].projectId;
    }

    function getUserBatchBalance(uint256 batchId, address user)
        external
        view
        returns (uint256)
    {
        return batchBalances[batchId][user];
    }

    function getTotalSupply() external view returns (uint256) {
        return totalSupply();
    }

    function getBatchSupply(uint256 batchId) external view returns (uint256) {
        return batchSupply[batchId];
    }

    function getBatchParent(uint256 batchId) external view returns (uint256) {
        return batchParent[batchId];
    }

    /**
     * @notice Point minting at an MRV oracle, or back to address(0) to disable.
     */
    function setMRVOracle(address oracle) external onlyRole(DEFAULT_ADMIN_ROLE) {
        mrvOracle = IMRVOracle(oracle);
        emit MRVOracleUpdated(oracle);
    }

    function isBatchFlagged(uint256 batchId) external view returns (bool) {
        return batches[batchId].isFlagged;
    }

    function grantMinterRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(MINTER_ROLE, account);
    }

    function grantVerifierRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(VERIFIER_ROLE, account);
    }

    function revokeMinterRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(MINTER_ROLE, account);
    }

    function revokeVerifierRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(VERIFIER_ROLE, account);
    }
}

contracts/interfaces/IMRVOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IMRVOracle
 * @notice Minimal measurement/reporting/verification (MRV) oracle surface.
 *
 * DA1 §2 identified "garbage in" as the core weakness of on-chain carbon
 * markets: a ledger can prove a credit was not double-spent, but not that the
 * tonnes behind it exist. This interface lets an off-chain MRV feed (satellite
 * imagery, soil sensors, registry API) attest to project data so minting can
 * require it.
 *
 * Implementations are deliberately trivial to mock: the on-chain contract only
 * needs the attestation, not the measurement itself.
 */
interface IMRVOracle {
    /// @notice keccak256 fingerprint of the evidence the oracle holds for a project.
    function getProjectHash(string calldata projectId) external view returns (bytes32);

    /// @notice True when the oracle has attested that the project data is valid.
    function isProjectApproved(string calldata projectId) external view returns (bool);

    /// @notice Tonnes of CO2e the oracle attests to for a project.
    function getVerifiedTonnage(string calldata projectId) external view returns (uint256);
}

contracts/Marketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./CreditToken.sol";

contract Marketplace is AccessControl, ReentrancyGuard {
    bytes32 public constant MARKETPLACE_ADMIN_ROLE = keccak256("MARKETPLACE_ADMIN_ROLE");
    bytes32 public constant BUYER_ROLE = keccak256("BUYER_ROLE");

    CreditToken public immutable creditToken;

    struct Listing {
        uint256 listingId;
        uint256 batchId;
        address seller;
        uint256 amount;
        uint256 pricePerToken;
        bool isActive;
        uint256 createdAt;
    }

    uint256 public listingCount;
    mapping(uint256 => Listing) public listings;
    mapping(address => uint256[]) public userListings;
    mapping(uint256 => mapping(address => uint256)) public listingPurchases;

    event ListingCreated(
        uint256 indexed listingId,
        uint256 indexed batchId,
        address indexed seller,
        uint256 amount,
        uint256 pricePerToken
    );
    event ListingCancelled(uint256 indexed listingId);
    event TokensPurchased(
        uint256 indexed listingId,
        uint256 indexed batchId,
        address indexed buyer,
        address seller,
        uint256 amount,
        uint256 totalPrice
    );
    event ListingUpdated(uint256 indexed listingId, uint256 newPrice);

    constructor(address _creditToken, address defaultAdmin) {
        creditToken = CreditToken(_creditToken);
        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(MARKETPLACE_ADMIN_ROLE, defaultAdmin);
        _grantRole(BUYER_ROLE, defaultAdmin);
    }

    function createListing(
        uint256 batchId,
        uint256 amount,
        uint256 pricePerToken
    ) external onlyRole(BUYER_ROLE) nonReentrant returns (uint256) {
        require(amount > 0, "Amount must be > 0");
        require(pricePerToken > 0, "Price must be > 0");
        require(creditToken.getUserBatchBalance(batchId, msg.sender) >= amount, "Insufficient batch balance");
        require(!creditToken.isBatchFlagged(batchId), "Batch is flagged");

        uint256 listingId = ++listingCount;
        Listing storage listing = listings[listingId];
        listing.listingId = listingId;
        listing.batchId = batchId;
        listing.seller = msg.sender;
        listing.amount = amount;
        listing.pricePerToken = pricePerToken;
        listing.isActive = true;
        listing.createdAt = block.timestamp;

        userListings[msg.sender].push(listingId);

        emit ListingCreated(listingId, batchId, msg.sender, amount, pricePerToken);
        return listingId;
    }

    function cancelListing(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender, "Only seller can cancel");
        require(listing.isActive, "Listing not active");

        listing.isActive = false;

        emit ListingCancelled(listingId);
    }

    function updateListingPrice(uint256 listingId, uint256 newPrice) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender, "Only seller can update price");
        require(listing.isActive, "Listing not active");
        require(newPrice > 0, "Price must be > 0");

        listing.pricePerToken = newPrice;

        emit ListingUpdated(listingId, newPrice);
    }

    function buyTokens(uint256 listingId, uint256 amount) external payable nonReentrant returns (uint256) {
        Listing storage listing = listings[listingId];
        require(listing.isActive, "Listing not active");
        require(amount > 0 && amount <= listing.amount, "Invalid amount");
        require(!creditToken.isBatchFlagged(listing.batchId), "Batch is flagged");

        // amount is in 18-decimal base units; pricePerToken is per whole credit
        uint256 totalPrice = (amount * listing.pricePerToken) / 1e18;
        require(totalPrice > 0, "Insufficient payment");
        require(msg.value >= totalPrice, "Insufficient payment");

        listing.amount -= amount;
        listingPurchases[listingId][msg.sender] += amount;

        creditToken.transferFrom(listing.seller, msg.sender, amount);

        if (msg.value > totalPrice) {
            payable(msg.sender).transfer(msg.value - totalPrice);
        }
        payable(listing.seller).transfer(totalPrice);

        if (listing.amount == 0) {
            listing.isActive = false;
        }

        emit TokensPurchased(listingId, listing.batchId, msg.sender, listing.seller, amount, totalPrice);
        return totalPrice;
    }

    function getListing(uint256 listingId)
        external
        view
        returns (
            uint256 batchId,
            address seller,
            uint256 amount,
            uint256 pricePerToken,
            bool isActive,
            uint256 createdAt
        )
    {
        Listing storage listing = listings[listingId];
        return (
            listing.batchId,
            listing.seller,
            listing.amount,
            listing.pricePerToken,
            listing.isActive,
            listing.createdAt
        );
    }

    function getActiveListings()
        external
        view
        returns (uint256[] memory)
    {
        uint256 activeCount = 0;
        for (uint256 i = 1; i <= listingCount; i++) {
            if (listings[i].isActive) activeCount++;
        }

        uint256[] memory activeListings = new uint256[](activeCount);
        uint256 idx = 0;
        for (uint256 i = 1; i <= listingCount; i++) {
            if (listings[i].isActive) {
                activeListings[idx] = i;
                idx++;
            }
        }
        return activeListings;
    }

    function getUserListings(address user)
        external
        view
        returns (uint256[] memory)
    {
        return userListings[user];
    }

    function getUserPurchases(uint256 listingId, address user)
        external
        view
        returns (uint256)
    {
        return listingPurchases[listingId][user];
    }

    function grantBuyerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(BUYER_ROLE, account);
    }

    function revokeBuyerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(BUYER_ROLE, account);
    }

    function grantMarketplaceAdminRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(MARKETPLACE_ADMIN_ROLE, account);
    }

    function withdrawEth() external onlyRole(MARKETPLACE_ADMIN_ROLE) {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contracts/RetireAndCertify.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./CreditToken.sol";

contract RetireAndCertify is ERC721URIStorage, AccessControl {
    bytes32 public constant RETIRE_ROLE = keccak256("RETIRE_ROLE");
    bytes32 public constant REGULATOR_ROLE = keccak256("REGULATOR_ROLE");

    CreditToken public immutable creditToken;

    struct Certificate {
        uint256 certificateId;
        address owner;
        uint256 batchId;
        uint256 amountRetired;
        string projectId;
        uint256 retirementTimestamp;
        string metadataURI;
    }

    uint256 private _certificateIds;
    mapping(uint256 => Certificate) public certificates;
    mapping(address => uint256[]) public userCertificates;
    mapping(uint256 => uint256) public batchTotalRetired;

    event CertificateMinted(
        uint256 indexed certificateId,
        address indexed owner,
        uint256 indexed batchId,
        uint256 amountRetired,
        string projectId
    );
    event BatchRetiredViaCertify(uint256 indexed batchId, uint256 amount, address indexed retiree);

    constructor(address _creditToken, address defaultAdmin)
        ERC721("Retirement Certificate", "RTC")
    {
        creditToken = CreditToken(_creditToken);
        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(RETIRE_ROLE, defaultAdmin);
        _grantRole(REGULATOR_ROLE, defaultAdmin);
    }

    function retireAndCertify(
        uint256 batchId,
        uint256 amount,
        string calldata metadataURI
    ) external onlyRole(RETIRE_ROLE) returns (uint256) {
        require(amount > 0, "Amount must be > 0");
        require(bytes(metadataURI).length > 0, "Metadata URI required");
        require(creditToken.getUserBatchBalance(batchId, msg.sender) >= amount, "Insufficient batch balance");
        require(!creditToken.isBatchFlagged(batchId), "Batch is flagged");

        creditToken.retireBatchFrom(msg.sender, batchId, amount);

        uint256 certificateId = ++_certificateIds;
        string memory projectId = creditToken.getBatchProjectId(batchId);

        Certificate storage cert = certificates[certificateId];
        cert.certificateId = certificateId;
        cert.owner = msg.sender;
        cert.batchId = batchId;
        cert.amountRetired = amount;
        cert.projectId = projectId;
        cert.retirementTimestamp = block.timestamp;
        cert.metadataURI = metadataURI;

        _safeMint(msg.sender, certificateId);
        _setTokenURI(certificateId, metadataURI);

        userCertificates[msg.sender].push(certificateId);
        batchTotalRetired[batchId] += amount;

        emit CertificateMinted(certificateId, msg.sender, batchId, amount, projectId);
        emit BatchRetiredViaCertify(batchId, amount, msg.sender);

        return certificateId;
    }

    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        // Get current owner before update
        address from = _ownerOf(tokenId);
        // Allow minting (from == address(0)) but not transfers
        if (from != address(0) && to != address(0)) {
            revert("Certificate is soulbound: cannot transfer");
        }
        return super._update(to, tokenId, auth);
    }

    function approve(address to, uint256 tokenId) public override(ERC721, IERC721) {
        revert("Certificate is soulbound: cannot approve");
    }

    function setApprovalForAll(address operator, bool approved) public override(ERC721, IERC721) {
        revert("Certificate is soulbound: cannot set approval");
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721URIStorage, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function getCertificate(uint256 certificateId)
        external
        view
        returns (
            address owner,
            uint256 batchId,
            uint256 amountRetired,
            string memory projectId,
            uint256 retirementTimestamp,
            string memory metadataURI
        )
    {
        Certificate storage cert = certificates[certificateId];
        return (
            cert.owner,
            cert.batchId,
            cert.amountRetired,
            cert.projectId,
            cert.retirementTimestamp,
            cert.metadataURI
        );
    }

    function getUserCertificates(address user)
        external
        view
        returns (uint256[] memory)
    {
        return userCertificates[user];
    }

    function getBatchTotalRetired(uint256 batchId) external view returns (uint256) {
        return batchTotalRetired[batchId];
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function grantRetireRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(RETIRE_ROLE, account);
    }

    function grantRegulatorRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(REGULATOR_ROLE, account);
    }

    function revokeRetireRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(RETIRE_ROLE, account);
    }

    function revokeRegulatorRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(REGULATOR_ROLE, account);
    }
}

contracts/VerifierStake.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./CreditToken.sol";

contract VerifierStake is AccessControl, ReentrancyGuard {
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant REGULATOR_ROLE = keccak256("REGULATOR_ROLE");
    bytes32 public constant CHALLENGER_ROLE = keccak256("CHALLENGER_ROLE");

    CreditToken public immutable creditToken;

    uint256 public constant MIN_STAKE = 1 ether;
    /// @notice Initial challenge window. Per-batch overrides may change it.
    uint256 public constant CHALLENGE_WINDOW = 90 days;
    uint256 public constant CHALLENGE_BOND = 0.1 ether;
    /// @notice Bounds for configurable challenge windows (roadmap 2).
    uint256 public constant MIN_CHALLENGE_WINDOW = 1 days;
    uint256 public constant MAX_CHALLENGE_WINDOW = 365 days;

    struct VerifierInfo {
        uint256 stake;
        uint256 lastTopUp;
        bool isActive;
    }

    struct Challenge {
        uint256 challengeId;
        uint256 batchId;
        address challenger;
        string evidenceHash;
        uint256 bond;
        uint256 timestamp;
        bool isResolved;
        bool challengerWon;
    }

    mapping(address => VerifierInfo) public verifiers;
    mapping(uint256 => Challenge) public challenges;
    mapping(uint256 => uint256[]) public batchChallenges;
    // Number of unresolved challenges against each verifier's batches
    mapping(address => uint256) public activeChallengeCount;
    uint256 public challengeCount;
    address public compensationPool;

    // --- Roadmap 2: configurable / per-batch challenge window ---
    /// @notice Window applied to batches without an explicit override.
    uint256 public defaultChallengeWindow = CHALLENGE_WINDOW;
    /// @notice Per-batch override; 0 means "use defaultChallengeWindow".
    mapping(uint256 => uint256) public batchChallengeWindow;

    // --- Roadmap 5: per-batch compensation pools with pro-rata claims ---
    /// @notice Funds still available to claim for a batch.
    mapping(uint256 => uint256) public batchCompensationPool;
    /// @notice Total ever credited to a batch pool, used as the pro-rata base.
    mapping(uint256 => uint256) public batchCompensationTotal;
    /// @notice Batch supply at resolution time; the pro-rata denominator.
    mapping(uint256 => uint256) public batchCompensationDenominator;
    /// @notice Per-claimant token count already used to claim, so a repeat
    /// claim is measured only against newly acquired tokens.
    mapping(uint256 => mapping(address => uint256)) public compensationClaimedTokens;

    event StakeDeposited(address indexed verifier, uint256 amount);
    event StakeWithdrawn(address indexed verifier, uint256 amount);
    event StakeSlashed(address indexed verifier, uint256 amount, address indexed recipient);
    event ChallengeCreated(
        uint256 indexed challengeId,
        uint256 indexed batchId,
        address indexed challenger,
        string evidenceHash
    );
    event ChallengeResolved(
        uint256 indexed challengeId,
        bool challengerWon,
        uint256 slashedAmount,
        address indexed recipient
    );
    event CompensationPoolUpdated(uint256 newBalance);
    event DefaultChallengeWindowUpdated(uint256 newWindow);
    event BatchChallengeWindowUpdated(uint256 indexed batchId, uint256 newWindow);
    event CompensationPoolDeposited(
        uint256 indexed batchId,
        uint256 amount,
        uint256 denominator
    );
    event CompensationClaimed(uint256 indexed batchId, address indexed claimant, uint256 amount);

    constructor(address _creditToken, address _compensationPool, address defaultAdmin) {
        creditToken = CreditToken(_creditToken);
        compensationPool = _compensationPool;
        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);
        _grantRole(VERIFIER_ROLE, defaultAdmin);
        _grantRole(REGULATOR_ROLE, defaultAdmin);
        _grantRole(CHALLENGER_ROLE, defaultAdmin);
    }

    function depositStake() external payable onlyRole(VERIFIER_ROLE) nonReentrant {
        require(msg.value >= MIN_STAKE, "Minimum stake is 1 ETH");
        VerifierInfo storage verifier = verifiers[msg.sender];
        verifier.stake += msg.value;
        verifier.lastTopUp = block.timestamp;
        verifier.isActive = true;
        emit StakeDeposited(msg.sender, msg.value);
    }

    function withdrawStake(uint256 amount) external onlyRole(VERIFIER_ROLE) nonReentrant {
        VerifierInfo storage verifier = verifiers[msg.sender];
        require(verifier.stake >= amount, "Insufficient stake");
        require(verifier.stake - amount >= MIN_STAKE || verifier.stake == amount, "Must maintain minimum stake");
        require(!hasActiveChallenges(msg.sender), "Active challenges exist");

        verifier.stake -= amount;
        if (verifier.stake < MIN_STAKE) {
            verifier.isActive = false;
        }
        payable(msg.sender).transfer(amount);
        emit StakeWithdrawn(msg.sender, amount);
    }

    function createChallenge(
        uint256 batchId,
        string calldata evidenceHash
    ) external payable onlyRole(CHALLENGER_ROLE) nonReentrant {
        require(msg.value >= CHALLENGE_BOND, "Minimum challenge bond is 0.1 ETH");
        require(bytes(evidenceHash).length > 0, "Evidence hash required");
        require(creditToken.getBatchVerifier(batchId) != address(0), "Batch not found");
        require(
            block.timestamp <= creditToken.getBatchTimestamp(batchId) + getChallengeWindow(batchId),
            "Challenge window expired"
        );

        uint256 challengeId = ++challengeCount;
        Challenge storage challenge = challenges[challengeId];
        challenge.challengeId = challengeId;
        challenge.batchId = batchId;
        challenge.challenger = msg.sender;
        challenge.evidenceHash = evidenceHash;
        challenge.bond = msg.value;
        challenge.timestamp = block.timestamp;
        challenge.isResolved = false;
        challenge.challengerWon = false;

        batchChallenges[batchId].push(challengeId);

        activeChallengeCount[creditToken.getBatchVerifier(batchId)]++;

        emit ChallengeCreated(challengeId, batchId, msg.sender, evidenceHash);
    }

    function resolveChallenge(
        uint256 challengeId,
        bool challengerWins
    ) external onlyRole(REGULATOR_ROLE) nonReentrant {
        Challenge storage challenge = challenges[challengeId];
        require(!challenge.isResolved, "Challenge already resolved");

        address verifier = creditToken.getBatchVerifier(challenge.batchId);
        VerifierInfo storage verifierInfo = verifiers[verifier];

        challenge.isResolved = true;
        challenge.challengerWon = challengerWins;

        uint256 slashedAmount = 0;
        if (challengerWins) {
            slashedAmount = verifierInfo.stake / 2;
            uint256 challengerReward = slashedAmount / 2;
            uint256 compensationAmount = slashedAmount - challengerReward;

            verifierInfo.stake -= slashedAmount;
            if (verifierInfo.stake < MIN_STAKE) {
                verifierInfo.isActive = false;
            }

            // Bond is returned plus the challenger's half of the slashed stake;
            // the other half is held in a per-batch pool for the buyers who
            // were left holding the fraudulent credits.
            payable(challenge.challenger).transfer(challenge.bond + challengerReward);

            // Roadmap 5: pro-rata pool instead of a single recipient address.
            batchCompensationPool[challenge.batchId] += compensationAmount;
            batchCompensationTotal[challenge.batchId] += compensationAmount;
            batchCompensationDenominator[challenge.batchId] = creditToken.getBatchSupply(challenge.batchId);

            creditToken.flagBatch(challenge.batchId, true);

            emit StakeSlashed(verifier, slashedAmount, challenge.challenger);
            emit CompensationPoolDeposited(
                challenge.batchId,
                compensationAmount,
                batchCompensationDenominator[challenge.batchId]
            );
        } else {
            payable(compensationPool).transfer(challenge.bond);
            emit CompensationPoolUpdated(address(compensationPool).balance);
        }

        if (activeChallengeCount[verifier] > 0) {
            activeChallengeCount[verifier]--;
        }

        emit ChallengeResolved(challengeId, challengerWins, slashedAmount, challengerWins ? challenge.challenger : compensationPool);
    }

    function getVerifierInfo(address verifier)
        external
        view
        returns (uint256 stake, uint256 lastTopUp, bool isActive)
    {
        VerifierInfo storage v = verifiers[verifier];
        return (v.stake, v.lastTopUp, v.isActive);
    }

    function getChallenge(uint256 challengeId)
        external
        view
        returns (
            uint256 batchId,
            address challenger,
            string memory evidenceHash,
            uint256 bond,
            uint256 timestamp,
            bool isResolved,
            bool challengerWon
        )
    {
        Challenge storage c = challenges[challengeId];
        return (c.batchId, c.challenger, c.evidenceHash, c.bond, c.timestamp, c.isResolved, c.challengerWon);
    }

    function getBatchChallenges(uint256 batchId)
        external
        view
        returns (uint256[] memory)
    {
        return batchChallenges[batchId];
    }

    function hasActiveChallenges(address verifier) internal view returns (bool) {
        return activeChallengeCount[verifier] > 0;
    }

    // ------------------------------------------------------------------
    // Roadmap 2: configurable challenge window
    // ------------------------------------------------------------------

    /// @notice Window that currently applies to a batch: its override if set,
    /// otherwise the global default.
    function getChallengeWindow(uint256 batchId) public view returns (uint256) {
        uint256 override_ = batchChallengeWindow[batchId];
        return override_ == 0 ? defaultChallengeWindow : override_;
    }

    function setDefaultChallengeWindow(uint256 window) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(
            window >= MIN_CHALLENGE_WINDOW && window <= MAX_CHALLENGE_WINDOW,
            "Window out of bounds"
        );
        defaultChallengeWindow = window;
        emit DefaultChallengeWindowUpdated(window);
    }

    function setBatchChallengeWindow(
        uint256 batchId,
        uint256 window
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(creditToken.getBatchVerifier(batchId) != address(0), "Batch not found");
        require(
            window >= MIN_CHALLENGE_WINDOW && window <= MAX_CHALLENGE_WINDOW,
            "Window out of bounds"
        );
        batchChallengeWindow[batchId] = window;
        emit BatchChallengeWindowUpdated(batchId, window);
    }

    /// @notice Clears a per-batch override so the batch falls back to the default.
    function clearBatchChallengeWindow(uint256 batchId) external onlyRole(DEFAULT_ADMIN_ROLE) {
        batchChallengeWindow[batchId] = 0;
        emit BatchChallengeWindowUpdated(batchId, defaultChallengeWindow);
    }

    // ------------------------------------------------------------------
    // Roadmap 5: per-batch compensation, pro-rata by batch holdings
    // ------------------------------------------------------------------

    /**
     * @notice Withdraw this sender's share of a slashed batch's compensation.
     * @dev The share is measured against the supply snapshot taken when the
     * challenge was resolved, so a holder who has since sold keeps only the
     * share their remaining balance entitles them to. Tokens acquired after
     * resolution are not claimable, and the denominator is frozen, so the pool
     * cannot be drained for more than it holds.
     */
    function claimCompensation(uint256 batchId) external nonReentrant returns (uint256) {
        uint256 total = batchCompensationTotal[batchId];
        require(total > 0, "No compensation pool");
        uint256 denominator = batchCompensationDenominator[batchId];
        require(denominator > 0, "No compensation denominator");
        // The verifier whose batch was flagged must not draw from the pool that
        // exists to compensate the buyers it misled.
        require(
            creditToken.getBatchVerifier(batchId) != msg.sender,
            "Verifier cannot claim compensation"
        );

        uint256 balance = creditToken.getUserBatchBalance(batchId, msg.sender);
        uint256 alreadyClaimed = compensationClaimedTokens[batchId][msg.sender];
        require(balance > alreadyClaimed, "Nothing to claim");

        uint256 claimableTokens = balance - alreadyClaimed;
        uint256 share = (total * claimableTokens) / denominator;
        require(share > 0, "Claim amount too small");

        uint256 available = batchCompensationPool[batchId];
        if (share > available) {
            share = available;
        }
        require(share > 0, "Compensation pool exhausted");

        compensationClaimedTokens[batchId][msg.sender] = balance;
        batchCompensationPool[batchId] = available - share;

        payable(msg.sender).transfer(share);
        emit CompensationClaimed(batchId, msg.sender, share);
        return share;
    }

    function grantVerifierRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(VERIFIER_ROLE, account);
    }

    function grantRegulatorRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(REGULATOR_ROLE, account);
    }

    function grantChallengerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(CHALLENGER_ROLE, account);
    }

    function revokeVerifierRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(VERIFIER_ROLE, account);
    }

    function revokeRegulatorRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(REGULATOR_ROLE, account);
    }

    function revokeChallengerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(CHALLENGER_ROLE, account);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

